import { test, expect } from "@playwright/test";

test.describe("TC-001: Locked-out user cannot log in", () => {
  test("should fail login for a locked-out user", async ({ page }) => {
    await page.goto("/");

    await page.locator('[data-test="username"]').fill("locked_out_user");
    await expect(page.locator('[data-test="username"]')).toHaveValue("locked_out_user");

    await page.locator('[data-test="password"]').fill("secret_sauce");
    await expect(page.locator('[data-test="password"]')).toHaveValue("secret_sauce");

    await page.locator('[data-test="login-button"]').click();

    await expect(page.locator('[data-test="error"]')).toHaveText(
      "Epic sadface: Sorry, this user has been locked out."
    );
    await expect(page).toHaveURL(/https:\/\/www\.saucedemo\.com\/?$/);
    await expect(page.locator('[data-test="inventory-container"]')).toHaveCount(0);
  });
});

