import { test, expect } from "@playwright/test";

import { loginAs } from "../support/auth";

test.describe("TC-002: Cart badge reflects added and removed items", () => {
  test("should add and remove items and reflect the correct cart badge", async ({ page }) => {
    await loginAs(page, "standard_user");

    await page.locator('[data-test="add-to-cart-sauce-labs-backpack"]').click();
    await expect(page.locator('[data-test="shopping-cart-badge"]')).toHaveText("1");

    await page.locator('[data-test="add-to-cart-sauce-labs-bike-light"]').click();
    await expect(page.locator('[data-test="shopping-cart-badge"]')).toHaveText("2");

    await page.locator('[data-test="remove-sauce-labs-backpack"]').click();
    await expect(page.locator('[data-test="shopping-cart-badge"]')).toHaveText("1");
    await expect(page.locator('[data-test="add-to-cart-sauce-labs-backpack"]')).toHaveText("Add to cart");

    await page.locator('[data-test="shopping-cart-link"]').click();
    await expect(page).toHaveURL(/cart/);

    const cartItems = page.locator('[data-test="inventory-item-name"]');
    await expect(cartItems).toHaveCount(1);
    await expect(cartItems.first()).toHaveText("Sauce Labs Bike Light");
  });
});

