arguments.file_text:
import { test, expect } from "@playwright/test";

import { loginAs } from "../support/auth";

test.describe("TC-003: Sort products by price, low to high", () => {
  test("should sort products by price low to high", async ({ page }) => {
    await loginAs(page, "standard_user");

    const sortDropdown = page.locator('[data-test="product-sort-container"]');
    await sortDropdown.selectOption("lohi");

    await expect(sortDropdown.locator("option:checked")).toHaveText("Price (low to high)");

    const prices = await page.locator('[data-test="inventory-item-price"]').evaluateAll((nodes) =>
      nodes.map((node) => Number(node.textContent?.replace(/[^\d.]/g, ""))),
    );

    expect(prices).toEqual([...prices].sort((a, b) => a - b));

    const products = await page.locator('[data-test="inventory-item"]').evaluateAll((nodes) =>
      nodes.map((node) => ({
        name: node.querySelector('[data-test="inventory-item-name"]')?.textContent?.trim(),
        price: node.querySelector('[data-test="inventory-item-price"]')?.textContent?.trim(),
      })),
    );

    expect(products[0]).toEqual({ name: "Sauce Labs Onesie", price: "$7.99" });
    expect(products[products.length - 1]).toEqual({
      name: "Sauce Labs Fleece Jacket",
      price: "$49.99",
    });
  });
});

