import { expect, test } from "@playwright/test";
import { loginAs } from "../support/auth";

test.describe("TC-005: Checkout overview shows the correct price summary", () => {
  test("should verify the checkout price summary", async ({ page }) => {
    await loginAs(page, "standard_user");
    await page.locator('[data-test="add-to-cart-sauce-labs-backpack"]').click();

    await page.locator('[data-test="shopping-cart-link"]').click();
    await page.locator('[data-test="checkout"]').click();
    await expect(page).toHaveURL(/checkout-step-one\.html/);
    await expect(page.locator("body")).toContainText("Checkout: Your Information");

    await page.locator('[data-test="firstName"]').fill("John");
    await page.locator('[data-test="lastName"]').fill("Doe");
    await page.locator('[data-test="postalCode"]').fill("12345");
    await page.locator('[data-test="continue"]').click();
    await expect(page).toHaveURL(/checkout-step-two\.html/);
    await expect(page.locator("body")).toContainText("Checkout: Overview");

    await expect(page.locator("body")).toContainText("Item total: $29.99");
    await expect(page.locator("body")).toContainText("Tax: $2.40");
    await expect(page.locator("body")).toContainText("Total: $35.39");
  });
});

